from typing import Iterable, Sequence

class EmptyDatasetError(ValueError):
    """Raised when an empty sequence is passed."""

def calculate_moving_average(values: Sequence[float], window_size: int) -> list[float]:
    if not values:
        raise EmptyDatasetError('Cannot compute moving average on an empty dataset.')
    if window_size <= 0:
        raise ValueError(f'window_size must be positive, got {window_size}')
    averages: list[float] = []
    current_window_sum = sum(values[:window_size])
    averages.append(current_window_sum / window_size)
    for i in range(window_size, len(values)):
        current_window_sum += values[i] - values[i - window_size]
        averages.append(current_window_sum / window_size)
    return averages

from __future__ import annotations
from dataclasses import dataclass
import math

@dataclass(frozen=True, slots=True)
class Vector2D:
    """Represents an immutable 2D Cartesian coordinate vector."""
    x: float
    y: float

    def magnitude(self) -> float:
        return math.hypot(self.x, self.y)

    def normalized(self) -> Vector2D:
        mag = self.magnitude()
        if mag == 0.0:
            raise ZeroDivisionError('Cannot normalize a null vector.')
        return Vector2D(self.x / mag, self.y / mag)

import hashlib
import hmac
import os
import secrets
from typing import Optional

class SecurityAuthService:
    def __init__(self, secret_key: Optional[bytes] = None) -> None:
        self._secret_key = secret_key or os.environ.get('AUTH_SECRET_KEY', secrets.token_bytes(32))
    def generate_secure_api_token(self, prefix: str = 'tok_') -> str:
        return f'{prefix}{secrets.token_urlsafe(32)}'
    def verify_signature(self, payload: bytes, signature_hex: str) -> bool:
        expected_sig = hmac.new(self._secret_key, msg=payload, digestmod=hashlib.sha256).hexdigest()
        return hmac.compare_digest(expected_sig, signature_hex)

import asyncio
import logging
from typing import Any, Callable, Coroutine, Sequence

logger = logging.getLogger(__name__)

async def fetch_with_semaphore(semaphore: asyncio.Semaphore, worker_fn: Callable[[int], Coroutine[Any, Any, str]], item_id: int, timeout_seconds: float = 5.0) -> str:
    async with semaphore:
        try:
            return await asyncio.wait_for(worker_fn(item_id), timeout=timeout_seconds)
        except asyncio.TimeoutError:
            return f'TIMEOUT: {item_id}'

